(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["lv"] = {"ui":{"skip":"Pāriet uz saturu","back":"← Atpakaļ uz AI-gile","lang.button":"Valoda: {name}","lang.dialog":"Izvēlies valodu","lang.search":"Meklēt valodas","lang.none":"Neviena valoda neatbilst","lang.notYet":"{name} vēl nav iztulkota","theme.aria":"Pārslēgt gaišo un tumšo tēmu","theme.toLight":"Pārslēgt uz gaišo tēmu","theme.toDark":"Pārslēgt uz tumšo tēmu","words.underline":"Pasvītrot šos vārdus lapā","words.underlineHelp":"Novieto kursoru uz vārda ar punktētu pasvītrojumu vai pieskaries tam, lai redzētu, ko tas nozīmē.","index.title":"AI-gile: tava MI izstrādes komanda vienā tāfelē","index.description":"AI-gile ir kanban tāfele MI programmēšanas komandām. Tās strādā, kamēr tu guli; tev paliek viena īsa kaudzīte: ko izlemt, ko pārbaudīt un ko pieņemt.","hero.logoAlt":"AI-gile tāfeles ikona","hero.h1.html":"Tava MI izstrādes komanda vienā&nbsp;tāfelē.","hero.alpha":"🐣 Slēgta pirmsalfa","hero.alphaTitle":"Agrīna un nepabeigta: paldies, ka izmēģini!","hero.lede":"Viņi būvē, kamēr tu guli. Pamodies tu atrodi vienu īsu kaudzīti: pāris jautājumu, pāris lietu, ko pārbaudīt, un viens otrs violets dimants. Uzklikšķini, pieņem un atpakaļ pie kafijas.","dl.windows":"Windows lietotne","dl.browser":"Palaid pārlūkā","dl.soon":"Drīzumā","dl.notify":"🔔 Pastāsti, kad atvērsies","dl.notifySmall":"Alfa vai beta","hero.secondary":"Agile, bet komandai nekad nevajag stāvošo rīta kafiju. (Stand-up viņi tāpat rīko.)","pitch.h2":"AI-gile tik vārdos, cik vēlies","pitch.lede":"Izvēlies garumu, no viena vārda līdz 144. Katrs garums ir savs apraksts, uzrakstīts tieši tam. Velc slīdni vai lieto bulttaustiņus.","pitch.rangeLabel":"Garums vārdos","pitch.dice":"🎲 cita versija","pitch.words.one":"{n} vārds","pitch.words.other":"{n} vārdi","pitch.letters.one":"{n} burts","pitch.letters.other":"{n} burti","pitch.chars.one":"{n} rakstzīme","pitch.chars.other":"{n} rakstzīmes","count.line.html.one":"Tāfelē šobrīd ir {n} kartīte","count.line.html.other":"Tāfelē šobrīd ir {n} kartītes","features.aria":"Ko tā dara","f.pile.h":"Viena kaudzīte tev","f.pile.html":"<b>Tev</b> satur visu, kas gaida tevi, no visiem projektiem: jautājumus, lietas, ko pārbaudīt, un uzdevumus, ko var izdarīt tikai cilvēks. Tava rinda parāda, kas ir nākamais un cik tas aizņems.","f.sleep.h":"Komandas, kas strādā, kamēr tu guli","f.sleep.p":"Katram projektam ir līderis un MI aģentu komanda. Komentē kartīti, un komanda pamostas, paveic darbu un atdod to atpakaļ ar soļiem, kurus var izpildīt arī nogurusi cilvēks.","f.tester.h":"Vispirms pārbauda MI testētājs","f.tester.p":"Pirms kaut kas nonāk pie tevis, testētājs izpilda soļus lietotnes kopijā un parāda redzēto ar ekrānuzņēmumu. Pārlapo izturējušos un pieņem ar vienu klikšķi.","f.proof.h":"Pierādījumi, nevis solījumi","f.proof.p":"Katra nodošana parāda, kas mainījies: failus, atšķirības, ekrānuzņēmumus. Nav jāatver katra lietotne, lai redzētu, vai viss gatavs.","f.chat.h":"Tērzē ar saviem līderiem","f.chat.p":"Discord stila josla: viena ikona katram projektam, violeti dimanti tam, kam vajag tevi. Uzraksti līderim ideju; viņš to pārvērš kartītēs un plānā ar pogu ✅ Aiziet.","f.tidy.h":"Pati uztur kārtību","f.tidy.p":"Saistītās kartītes saplūst vienā, juceklīgi nosaukumi tiek sakārtoti, un tokenu pārbaude uztur kodu kompaktu. Mazāk, starp ko pārslēgties, mazāk, par ko domāt.","f.private.h":"Tava, tavā datorā","f.private.li1":"Tāfele darbojas tavā paša datorā un atbild tikai tev.","f.private.li2":"Privātās ziņas starp cilvēkiem ir šifrētas no gala līdz galam.","f.private.li3":"Nekādu kontu, izsekotāju un sīkdatņu.","f.lang.h":"Tavā valodā","f.lang.p":"Vairāk nekā 120 valodu, no holandiešu, velsiešu un japāņu līdz pirātu, Jodas un klingonu valodai, ar ātru pārslēgšanos atpakaļ uz angļu valodu izstrādātāju vārdiem.","tl.aria":"Laika līnija no pirmās sarunas līdz ceļvedim","tl.h2":"No pirmās sarunas līdz tam, kas sekos","tl.lede":"Īsti datumi un laiki tavā laika joslā. Pēc šodienas tas ir plāns, bez solītiem datumiem.","tl.today":"Šodien","tl.planned":"plānots","tl.cards.one":"{n} kartīte","tl.cards.other":"{n} kartītes","join.h2":"Pievienojies","join.lede":"AI-gile veido viens mazs cilvēks un liels pulks pacietīgu aģentu. Pagaidām tā ir privāta, slēgtā alfā kopā ar draugiem. Vai gribi izmēģināt, kad tā atvērsies?","join.btn":"Pieteikt interesi","join.small":"Mēs uzrakstīsim e-pastu un neko citu","footer.tag":"AI-gile. Nekādu izsekotāju, nekādu sīkdatņu, nekādas stāvošās rīta kafijas.","footer.licence":"Biznesa licence","footer.status":"Statuss","footer.privacy":"Ko mēs glabājam","form.sending":"Sūta…","form.failed":"Neizdevās: mēģini vēlāk vēlreiz.","form.offline":"Neizdevās sazināties ar AI-gile: mēģini vēlāk vēlreiz.","form.keep":"Mēs to izmantojam tikai, lai tev atbildētu, un pēc tam izdzēšam. Nekādu izsekotāju, nekādu sīkdatņu.","form.keepLink":"Ko mēs glabājam","interest.title":"AI-gile: pastāsti, kad atvērsies alfa","interest.description":"Atstāj savu e-pastu, lai uzzinātu, kad atvērsies AI-gile slēgtā alfa vai beta.","interest.h1":"🔔 Pastāsti, kad atvērsies","interest.lede":"AI-gile ir slēgtā pirmsalfā. Atstāj e-pastu, un mēs uzrakstīsim vienreiz, kad tev būs vieta.","interest.email":"Tavs e-pasts","interest.which":"Kuru testu?","interest.alpha":"Slēgtā alfa: agrīna, raupja, daudz izmaiņu","interest.beta":"Beta: stabilāka, vēlāk","interest.both":"Jebkuru, kas būs pirmā","interest.submit":"Pieraksti mani sarakstā","interest.thanks":"Paldies! Tu esi sarakstā.","licence.title":"AI-gile: biznesa licence","licence.description":"Lieto AI-gile savā uzņēmumā? Pieprasi bezmaksas biznesa licenci.","licence.h1":"📜 Biznesa licence","licence.lede":"Lieto AI-gile darbā? Pastāsti, kas tu esi un ar ko nodarbojies. Ja tas nes kādu labumu, licence ir bez maksas.","licence.company":"Uzņēmums","licence.website":"Tīmekļa vietne","licence.what":"Ar ko nodarbojies","licence.how":"Kā tas palīdz pasaulei","licence.email":"E-pasts","licence.submit":"Pieteikties","licence.thanks":"Paldies! Atbildēsim pa e-pastu.","status.title":"AI-gile statuss","status.h1":"AI-gile statuss","status.quiet":"Viss mierīgi","status.intro":"Vai AI-gile šobrīd darbojas? Šī lapa ik pēc 5 minūtēm pārbauda vietni, tāfeļu koplietošanu, zvanus un lejupielādi.","status.up":"Darbojas (atbildēja {ms} ms laikā)","status.slow":"Neatbildēja uz pēdējo pārbaudi, mēģina vēlreiz","status.down":"Nedarbojas: neatbildēja uz pēdējām divām pārbaudēm","status.svc.web":"Vietne","status.svc.web.offers":"Šī vietne: kas ir AI-gile, un interešu pieteikuma veidlapa","status.svc.boards":"Tāfeļu koplietošana","status.svc.boards.offers":"Publiskas tāfeles, ziņas starp draugiem un ielūgumi","status.svc.calls":"Zvani","status.svc.calls.offers":"Balss, video un ekrāna kopīgošana AI-gile","status.svc.download":"Lejupielāde","status.svc.download.offers":"Windows instalētājs un ielūgumu saites","status.checking":"Pārbauda…","status.offline":"Šobrīd nevar sazināties ar statusa pakalpojumu (mēģina vēlreiz)","status.updated":"atjaunināts {ago}","status.justNow":"tikko","status.min":"pirms {n} min","status.hours":"pirms {n} h","status.days":"pirms {n} d","privacy.title":"AI-gile: ko mēs glabājam","privacy.h1":"Ko mēs glabājam","privacy.lede":"Īsumā: tikai to, ko tu mums nosūti, un ne ilgi.","privacy.only":"Tikai to, ko tu mums nosūti: to, ko ieraksti veidlapā, piemēram, savu e-pastu. Neko citu par tevi.","privacy.sealed":"Tas tiek aizzīmogots, lai mūsu serveris to nevarētu izlasīt: jau tavā pārlūkā, pirms tas tiek nosūtīts (vecākā pārlūkā tajā brīdī, kad tas pienāk). Atvērt to var tikai mūsu pašu tāfele.","privacy.server":"No servera tas tiek izdzēsts, tiklīdz nonāk mūsu tāfelē. Viss, kas tur vēl ir pēc 30 dienām, tiek izdzēsts jebkurā gadījumā.","privacy.board":"Mūsu tāfelē mēs to glabājam tikai līdz brīdim, kad esam tev atbildējuši, un tad izdzēšam arī tur.","privacy.none":"Nekādu izsekotāju, nekādu sīkdatņu, nekādas analītikas.","privacy.local":"Tava valoda un gaišās vai tumšās tēmas izvēle paliek tavā pārlūkā. Tās nekad netiek sūtītas mums.","privacy.ask":"Gribi, lai to izdzēšam ātrāk? Atbildi uz mūsu e-pastu un pasaki to.","live.h2":"Skaties, kā tas top, tiešraidē","live.caption":"Katra kartīte ir paslēpta: tu redzi darba formu, nevis vārdus.","live.watching.one":"tiešraidē: {n} skatās","live.watching.other":"tiešraidē: {n} skatās","live.last.now":"Pēdējā kartīte pārvietota tikko","live.last.min.one":"Pēdējā kartīte pārvietota pirms {n} min.","live.last.min.other":"Pēdējā kartīte pārvietota pirms {n} min.","live.last.hour.one":"Pēdējā kartīte pārvietota pirms {n} st.","live.last.hour.other":"Pēdējā kartīte pārvietota pirms {n} st.","live.last.day.one":"Pēdējā kartīte pārvietota pirms {n} d.","live.last.day.other":"Pēdējā kartīte pārvietota pirms {n} d.","live.offline":"Tiešraides tāfele mazliet atpūšas. Ieskaties drīz vēlreiz.","live.cols":"Backlogs|Darāmais|Procesā|Komanda pārbauda|Gaida tavu testu|Komandai|Izdarīts","pitch.words.zero":"{n} vārdu","pitch.letters.zero":"{n} burtu","pitch.chars.zero":"{n} rakstzīmju","count.line.html.zero":"Tāfelē šobrīd ir {n} kartīšu","tl.cards.zero":"{n} kartīšu"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboti.","Deleģēts."]},{"n":2,"texts":["Robotu kanban.","Aģenti, sakārtoti.","Idejas, uzbūvētas."]},{"n":3,"texts":["Kanban robotiem.","Idejas kļūst funkcijās.","Bezmaksas aģentu kanban."]},{"n":5,"texts":["Kanban tāfele, ko vada aģenti.","Tu raksti kartītes. Aģenti būvē.","Bezmaksas, vietēja, pārbaudīta, mazliet jocīga."]},{"n":8,"texts":["Bezmaksas kanban tāfele, kur strādā MI aģenti.","Uzraksti ideju. Aģenti to uzbūvē. Tu to pieņem.","Agile vienam cilvēkam un daudziem pacietīgiem robotiem."]},{"n":13,"texts":["Kanban tāfele tavā datorā, kurā kartītes pa vienai paņem MI aģenti, kamēr tu atpūties.","Uzraksti ideju. To uzbūvē aģentu komanda. Pēc tam testētājs to rūpīgi pārbauda un parāda.","Bez kontiem, bez izsekotājiem: tāfele, daži roboti un tu, kas visu izlemj."]},{"n":21,"texts":["AI-gile ir kanban tāfele darbam ar MI programmēšanas aģentiem. Viņi paņem kartītes, bet tu tās pārbaudi un pieņem.","Katram projektam ir savs līderis un MI aģentu komanda. Komentē jebkuru kartīti, un komanda uzreiz ķeras pie darba.","Bezmaksas personīga darāmo lietu tāfele, kas darbojas tavā datorā. Darbinieki ir roboti. Tas, kurš saka jā, esi tu."]},{"n":34,"texts":["Tu liec idejas uz tāfeles. MI aģentu komanda pārvērš tās strādājošās funkcijās, pārbauda un atdod atpakaļ ar soļiem, kā izmēģināt. Nekas nav gatavs, kamēr tu to neesi pateicis.","AI-gile ir mājās darināta kanban tāfele, ko uzbūvēja Rich, lielā mērā ar to aģentu palīdzību, kurus tā tagad vada. Tā ir bezmaksas, darbojas tavā datorā un tiek dalīta ar draugiem, nevis pārdota.","Iedomājies parastu kanban tāfeli ar kolonnām no Backloga līdz Izdarītam, tikai kartītes paņem MI aģenti. Viņi ziņo par progresu, jautā, kad iestrēguši, un vienmēr gaida tavu īkšķi uz augšu."]},{"n":55,"texts":["AI-gile ir kanban tāfele, kurā komanda sastāv no MI aģentiem. Katram projektam ir līderis, kas plāno darbu, un palīgi, kas to būvē. Kad funkcija ir gatava, MI testētājs to izmēģina un uzņem ekrānuzņēmumu, tad tā nonāk tavā kaudzītē. Pieņem to vai komentē, un viņi darbu pārstrādā.","Tas sākās kā viena cilvēka veids, kā sekot daudzām MI programmēšanas sesijām vienlaikus, un izauga par īstu tāfeli. Tā darbojas tavā datorā, nevajag konta un nav izsekotāju. Tā ir bezmaksas draugiem un ikvienam ziņkārīgajam. Tā ir arī nepabeigta, tāpēc gaidi raupjas malas un reizēm kādu pārsteigumu.","Lūk, godīgā versija. Idejas tev joprojām jāizdomā, un rezultāti tev joprojām jāpārbauda. AI-gile dara visu pa vidu: tur kārtībā kartītes, pamodina īsto aģentu, kad tu komentē, parāda, kas tieši mainījies, un visu savāc vienā īsā kaudzītē, lai tev nav jāmeklē pa visiem projektiem un jāpārslēdzas starp lietotnēm."]},{"n":89,"texts":["AI-gile ir bezmaksas kanban tāfele, ko tu palaid savā datorā. Cilvēku vietā katram projektam ir sava MI aģentu komanda: līderis, kas tavas idejas pārvērš kartītēs un plānā, un palīgi, kas kartītes ķer pēc prioritātes. Kad kaut kas uzbūvēts, MI testētājs izpilda testa soļus un parāda, ko redzēja. Tad tas gaida vienā kaudzītē ar nosaukumu Tev. Tu to pieņem vai komentē, un komanda mēģina vēlreiz, ja vajag. Līdz Izdarīts nekas nenonāk bez tevis.","Dažas lietas, ko varbūt negaidi. Nakts sardze, kamēr tu guli, papildina kolonnu Darāmais ar kartītēm, kurām nevajag tavu atbildi. Tokenu skaitītājs rāda, cik aģenti šodien un šonedēļ iztērējuši, un režīms Bez tokeniem liek viņiem pārstāt tērēt. Tu vari rakstīt draugiem, un privātās ziņas ir šifrētas no gala līdz galam. Tāfele runā aptuveni 120 valodās, tostarp holandiešu, flāmu, pirātu un klingonu. Nekas no tā nemaksā ne santīma, un neviens arī necenšas tev to pārdot.","AI-gile ir neliels personīgs projekts, nevis uzņēmums. Rich gribēja pieskatīt vairākus MI programmēšanas projektus, neatverot katru lietotni, tāpēc viņš un aģenti uzbūvēja tāfeli, un tad ar to uzbūvēja pārējo pašu. Tā ir slēgtā pirmsalfā, kas nozīmē, ka lielākoties tā darbojas, bet to izmēģina tikai daži draugi. Neviens neko nepārdod, neviens nevāc tavus datus. Nav cenu lapas, nav jaunumu vēstuļu un nav izaugsmes plāna. Ja šķiet noderīgi, vari pieteikties izmēģināt, kad tā atvērsies nedaudz plašāk."]},{"n":144,"texts":["AI-gile ir kanban tāfele vienam cilvēkam un daudziem MI aģentiem. Tā darbojas tavā paša datorā un ir pilnīgi bezmaksas. Tu pievieno projektus, un katram projektam ir līderis un neliela komanda. Tu tērzē ar līderi, mazliet kā Discord, un apraksti ideju; līderis to pārvērš kartītēs un plānā, un tad gaida, kad nospiedīsi Aiziet. Komanda kartītes izstrādā pēc prioritātes, izmantojot vienkāršu komandrindu, kas radīta valodas modeļiem. Pirms kaut kas atgriežas pie tevis, MI testētājs izpilda soļus lietotnes kopijā un pievieno ekrānuzņēmumu. Pabeigtais darbs nonāk tavā kaudzītē kopā ar mainītajiem failiem un atšķirībām. Tu to pieņem vai atstāj komentāru, un komanda pamostas un mēģina vēlreiz. Tāfele sevi arī uzkopj: saistītās kartītes tiek apvienotas, un juceklīgi nosaukumi sakārtoti. Kartīti uz Izdarīts var pārvietot tikai tu. Neviens cits to nevar, pat visizcilākais aģents ne.","Aptuveni tāda ir diena ar AI-gile. Vakarā tu atstāj dažus komentārus: šī poga ir nepareizā vietā, šis saraksts jākārto, vai varētu būt tumšais režīms. Tu ej gulēt. Aģenti izlasa komentārus, veic izmaiņas, pārbauda tās un atdod tev atpakaļ. Ja Darāmais izsīkst, nakts sardze to papildina no backloga ar kartītēm, kurām nevajag tavu atbildi. Rītā ir viena īsa kaudzīte: pāris jautājumu un dažas lietas, ko izmēģināt, katrai ar soļiem, ko var izpildīt miegains cilvēks, un ekrānuzņēmumu, kā tas strādā. Tu pārklikšķini, pieņem labās un atsūti atpakaļ pārējās. Ja kaut kas nav skaidrs, tu vienkārši komentē, un tas atkal nonāk pie komandas. Tokenu skaitītājs rāda, cik tas viss patērēja, un režīms Bez tokeniem ir tievām nedēļām. Tad tu brokasto, kam aģenti vēl nevar palīdzēt.","Vispirms, kas AI-gile nav. Tas nav jaunuzņēmums, tas netiek pārdots, un neviens nevāc tavus datus. Tā ir bezmaksas tāfele, kas darbojas tavā datorā, bez kontiem, bez izsekotājiem un bez sīkdatnēm. Kas tā ir: viena kārtīga vieta, kur uzreiz redzēt visus MI programmēšanas projektus, kur kartītes dara aģentu komanda, bet lēmumus pieņem tu. Tajā ir arī nakts sardze, kas kartītes sagatavo, kamēr tu guli. Tā apvieno saistītās kartītes, sakārto juceklīgus nosaukumus un pieskata, cik kompakts paliek kods. Tā runā aptuveni 120 valodās, no holandiešu un flāmu līdz pirātu un klingonu. Draugi var sūtīt viens otram ziņas, privāti un šifrēti. To uzbūvēja Rich un liels pulks pacietīgu aģentu, galvenokārt izmantojot pašu tāfeli. Tā ir slēgtā pirmsalfā, tāpēc dažviet vēl ir raupja. Ja šķiet jautri, pieklājīgi pajautā, un varbūt tiksi iekšā agrāk."]}],"quips":{"1":"Viens vārds. Drosmīgi. Varbūt pat pārāk drosmīgi.","3":"Trīs vārdi. Jau godīgāk nekā vairums produktu lapu.","8":"Astoņi vārdi. Joprojām īsāk par stand-up.","21":"Garumi, starp citu, ir stāstu punkti. Protams, ka ir.","55":"Piecdesmit pieci vārdi. Kamēr tu to lasīji, divas kartītes tika pabeigtas.","144":"Tas ir garais. 233 nav. Aģenti ir aizgājuši gulēt."}},"timeline":{"first-idea.name":"Pirmā ideja","first-idea.line":"Pati pirmā saruna, pirms vēl bija kāds kods.","first-board.name":"Pirmā tāfele","first-board.line":"Tāfele, kas seko savai būvei: kartītes, kolonnas, vilkšana, projekti.","team-roles.name":"Komanda un lomas","team-roles.line":"Aģentu profili, komandu veidnes, telpas un kurš ko dara.","install.name":"Uzstādīšana un laidieni","install.line":"Zip, ko draugs var uzstādīt, pašatjaunināšanās, kanāli un atgriešanās.","usage-saver.name":"Patēriņa taupītājs","usage-saver.line":"Mēra, cik izmaksā darbs, uztur kodu kompaktu, taupa tavu limitu.","friends.name":"Draugi un kopīgošana","friends.line":"Privātas ziņas, sajaukts releja kanāls, ielūgumi, lomas un kopīgi projekti.","languages.name":"Valodas","languages.line":"Katrs ekrāna teksts valodas failā, vispirms holandiešu un flāmu valoda.","ai-tester.name":"MI testētājs","ai-tester.line":"Testētājs vispirms pārbauda katru nodošanu un parāda redzēto.","website.name":"Mājaslapa","website.line":"aigile.lol, ievada lapa un šī laika līnija.","streaming.name":"Tērzēšana un straumēšana","streaming.line":"Discord, Twitch, OBS, straumētāja režīms, GIF un emocijzīmes.","no-ai.name":"Izdevums bez MI","no-ai.line":"Tāfele cilvēkiem, kas programmē bez MI, un publiskas tāfeles.","night-watch.name":"Nakts sardze","night-watch.line":"Sargs un Scrum Master notur komandas pie darba, kamēr tu guli.","p-more.name":"Viss pārējais","p-more.line":"Mazākas idejas, kas vēl gaida savu kārtu.","p-android.name":"Telefons un Android","p-android.line":"Piekļuve tāfelei no telefona, pēc tam dabiska Android lietotne.","p-release.name":"Alfa un tālāk","p-release.line":"Slēgtā alfa, dzīvā vietne, tad beta.","p-languages.name":"Vairāk valodu","p-languages.line":"Vairāk nekā simts valodu un iegremdēšanās režīms apguvējiem.","p-engines.name":"Vairāk MI dzinēju","p-engines.line":"Izvēlies Claude, Codex vai Gemini katram aģentam.","p-pro.name":"Profesionāla prakse","p-pro.line":"Riska atzīmes, sapludināšanas vārti, incidentu kartītes un aizsargbarjeras.","p-self.name":"Rūpes par tevi","p-self.line":"Noguruma režīms, atgādinājumi par sevis kopšanu un 4:20.","p-servers.name":"Serveri un mērogs","p-servers.line":"Globāli servera iestatījumi, lomas un plānošana izaugsmei.","p-livestream.name":"Straumēšanas papildinājumi","p-livestream.line":"Twitch tērzētava, pašu emocijzīmes un publisks tiešraides skats."},"words":{"button":"📖 Izstrādātāju vārdi","h":"📖 Words explained","intro":"The words you meet in AI-gile, in plain language: building it, changing it safely, keeping it running for the people who use it, and working as a team with AI.","search":"Meklēt vārdu…","none":"Neviens vārds neatbilst.","close":"Aizvērt","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Building it"},{"id":"change","name":"🔀 Changing it safely"},{"id":"run","name":"🛎️ Running a service"},{"id":"team","name":"🤝 Working as a team (and with AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Projekta koda mape un tās pilnā commit vēsture, parasti glabāta arī GitHub.","also":["repozitorijs","repozitorija"]},{"id":"branch","g":"build","word":"Branch","text":"Atsevišķa darba līnija kodā, lai izmaiņas varētu veikt, neskarot galveno versiju.","also":["branches","zars","zara","zari"]},{"id":"commit","g":"build","word":"Commit","text":"Saglabāts koda momentuzņēmums ar īsu piezīmi par to, kas mainījās. Vienmēr var atgriezties pie kāda no tiem.","also":["commits","commiti","commita","commitu"]},{"id":"push","g":"build","word":"Push","text":"Saglabāto momentuzņēmumu (commit) sūtīšana no šī datora uz GitHub, lai tie būtu dublēti un kopīgoti."},{"id":"merge","g":"build","word":"Merge","text":"Zara izmaiņu apvienošana atpakaļ galvenajā versijā."},{"id":"pr","g":"build","word":"Pull request","text":"Lūgums pārbaudīt zara izmaiņas un apvienot tās galvenajā versijā.","also":["PR"]},{"id":"refactor","g":"build","word":"Refaktorēšana","text":"Koda sakārtošana, nemainot to, ko tas dara: mazāki faili, skaidrāki nosaukumi, mazāk atkārtojumu."},{"id":"bug","g":"build","word":"Kļūda","text":"Kaut kas, kas nedarbojas tā, kā vajadzētu.","also":["kļūdas","kļūdu","kļūdai","kļūdām","bugs","bugi","buga"]},{"id":"test","g":"build","word":"Tests","text":"Pabeigta darba izmēģināšana, lai pārbaudītu, vai tas dara to, kas prasīts, pirms to pieņem.","also":["testi","testa","testu","testam","testēt","testēšanai","testēšana","testējami","testējams","jātestē"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Short for quality assurance: the automatic checks that run before anything goes live. When QA is red, something failed, and it can’t go live until that is fixed.","also":["quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Jaunas versijas padarīšana pieejamai, piemēram, serverī, kur to lieto cilvēki."},{"id":"release","g":"change","word":"Release","text":"A named bundle of finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Going back to the last version that worked when a new one causes trouble. In AI-gile it makes a checklist of the undo steps written on each change.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that people use, as opposed to a copy for trying things out. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to something people rely on, written down first: what, why, the risk, when, and how to undo it. Start one with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Something that could go wrong, scored on how likely and how bad it would be. ⚠️ Risks keeps them in one list, highest score first, each with a date to look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes may go live, such as a quiet Tuesday evening. Outside a window a change card can’t be finished, unless it is an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A quick vote just before a change goes live: each person who has to approve says Go or No go. It only goes ahead when they agree.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waiting for a yes before work starts. A card a friend raises, or a change, waits in ✅ Approvals until you approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch of time, like a stream, a demo or the night, when nothing goes live. The teams keep working and testing, but going live waits until it ends. Elsewhere it is called a change freeze.","also":["quiet times","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Something you built that people rely on, like a website or an app, looked after so it keeps working. Tick “This project is a service” and say what it offers, who uses it and who is on call.","also":["services"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that your service still answers. If it fails several times in a row, AI-gile opens an incident card by itself.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is working (green, orange or red) with the latest update, so the people who use it can check instead of asking.","also":["status pages"]},{"id":"incident","g":"run","word":"Incident","text":"Something that is broken for the people using it right now, like the website being down. A 🔥 incident card jumps the queue: getting it working again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A big incident: many people affected, or money or data at risk. One button puts every team on it (swarm), wakes whoever is on call and asks for a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Being the one who answers when something breaks, even at night. Each service has an on-call team member who is woken first for its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card may wait for a first answer, for example an hour for an incident. After that it gets a red clock, so nothing is quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after an incident: what happened, what helped and what to change, without blaming anyone. An incident can’t be closed without one.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more incidents. A 🧩 problem card groups incidents that keep coming back, so the cause is found and fixed for good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason something broke, not just what you saw going wrong. Fix the root cause and the incident stops coming back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep things working until the real fix is ready, like restarting something when it gets stuck. It is written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause is understood and that has a workaround, but isn’t fixed yet. 🧩 Known errors lists them, so everyone uses the workaround instead of digging again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions for fixing a known kind of trouble, so it is done the same way, quickly, every time. After a big incident the team can propose one for you to OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy of your data from earlier, to fall back on if something is lost or damaged. AI-gile makes a backup of your boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Putting data back from a backup. A backup only really counts once you know it can be restored, so it is worth trying now and then.","also":["restored"]},{"id":"backlog","g":"team","word":"Backlogs","text":"Idejas un darbs, kas vēl nav ieplānots. Nekas no tā netiek darīts, kamēr tas nepāriet uz Darāmais."},{"id":"sprint","g":"team","word":"Sprints","text":"Īss darba posms (bieži nedēļa vai divas) ar saskaņotu kartīšu kopu, kas jāpabeidz.","also":["sprinti","sprinta","sprintu","sprintam","sprintiem","sprintā","sprintos"]},{"id":"standup","g":"team","word":"Stand-up","text":"Īsa ikdienas sapulce: ko katrs komandas dalībnieks izdarīja, ko darīs tālāk un kas kavē darbu.","also":["standup","stand-upi","stand-upa","stand-upu"]},{"id":"kanban","g":"team","word":"Kanban","text":"Dēlis ar kolonnām (Darāmais, Procesā, Izdarīts), kurā kartītes darba gaitā pārvietojas no kreisās uz labo."},{"id":"wip","g":"team","word":"WIP limits","text":"Procesā esošais darbs: cik kartīšu kolonnā drīkst būt visvairāk, lai komanda lietas pabeidz, pirms sāk jaunas.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"The team’s short checklist of what “finished” means, like tested and explained, before a card is handed to you. Its twin, the Definition of Ready, says when a card is clear enough to start.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"The finished cards waiting for you to try, one after another. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"A look back at how the team works, to agree on one thing to do better. In AI-gile a retro suggests a change to the team’s ways of working, and you say Go or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"A second pair of eyes: another AI checks each card’s work before it reaches you, so fewer mistakes get through.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"All hands on deck: every team drops other work to help on one urgent project until it is sorted. Other projects wait meanwhile.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"The one who keeps the work flowing: spots stuck cards, nudges the teams and reminds you of what is waiting. In AI-gile the Lead Scrum Master does this across every project.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Aģents","text":"MI, kas pie uzdevuma strādā patstāvīgi: lasa kodu, veic izmaiņas, palaiž pārbaudes un ziņo atpakaļ.","also":["aģenti","aģenta","aģentu","aģentiem","agent","agents"]},{"id":"token","g":"team","word":"Tokens","text":"Vienība, kurā skaita MI lietojumu: apmēram daži teksta burti, kas izlasīti vai uzrakstīti. Jo mazāk tokenu, jo vairāk plāna atlicis.","also":["tokeni","tokena","tokenu","tokeniem","token","tokens"]},{"id":"hook","g":"team","word":"Āķis","text":"Neliela komanda, kas pati darbojas noteiktā brīdī, piemēram, kad sākas MI sesija, lai komanda dzirdētu tavus komentārus.","also":["hook","hooks","āķi","āķa","āķu"]}]}};
